select id, customer_id, account_type, balance, opened_date, status, avg(balance) over (partition by account_type, status order by balance, id rows between 6 preceding and 1 preceding) as balance_avg_6_prior, percent_rank() over (partition by customer_id order by balance desc) as balance_percent_rank, sum(balance) over (partition by status order by opened_date, id rows between unbounded preceding and current row) as cumulative_balance, ntile(10) over (partition by customer_id order by balance, id) as balance_bucket, ntile(4) over (partition by account_type order by balance desc, id) as balance_bucket_2 from accounts
